<?php declare( strict_types=1 ); namespace Inc\Services\Exam; use Inc\DTO\Exam\ExamEventDTO; use Inc\Repositories\WPDBRepositories\ExamEventRepository; class ExamEventService { private ExamEventRepository $repo; public function __construct( ?ExamEventRepository $repo = null ) { $this->repo = $repo ?? new ExamEventRepository(); } public function createEvent( string $subjectKey, string $title, int $ownerUserId, string $periodFrom, string $periodTo, array $data = [] ): int { $defaults = [ 'subject_key' => $subjectKey, 'title' => $title, 'owner_user_id' => $ownerUserId, 'status' => 'draft', 'period_from' => $periodFrom, 'period_to' => $periodTo, 'created_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ), ]; return $this->repo->insert( array_merge( $defaults, $data ) ); } public function getEvent( int $eventId ): ?ExamEventDTO { return $this->repo->find( $eventId ); } public function publishEvent( int $eventId ): bool { return $this->repo->update( $eventId, [ 'status' => 'published', 'published_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ), ] ); } public function cancelEvent( int $eventId, string $reason ): bool { return $this->repo->update( $eventId, [ 'status' => 'cancelled', 'cancel_reason' => $reason, 'cancelled_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ), ] ); } public function completeEvent( int $eventId ): bool { return $this->repo->update( $eventId, [ 'status' => 'completed', 'completed_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ), ] ); } }
